import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.DpieW3qv.js";const p=JSON.parse('{"title":"Excel Operating Manual","description":"","frontmatter":{"title":"Excel Operating Manual"},"headers":[],"relativePath":"excel/index.md","filePath":"excel/index.md","lastUpdated":null}'),i={name:"excel/index.md"};function n(l,e,s,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="excel-operating-manual" tabindex="-1">Excel Operating Manual <a class="header-anchor" href="#excel-operating-manual" aria-label="Permalink to &quot;Excel Operating Manual&quot;">​</a></h1><p>The wireframe (Excel or Smartsheet) drives the CLI. This section explains the format, validation, and how to fix errors.</p><h2 id="what-the-excel-file-is" tabindex="-1">What the Excel file is <a class="header-anchor" href="#what-the-excel-file-is" aria-label="Permalink to &quot;What the Excel file is&quot;">​</a></h2><ul><li>A single workbook (or Smartsheet export) that describes <strong>changeouts</strong>: what content goes live on which dates.</li><li>Rows are grouped by refresh (name + date). Each row can specify ASSET TYPE, ZONE, ACTION, COPY, and link destinations.</li><li>The CLI reads this file (via <code>make pull</code> or a configured path), parses it into <strong>refreshes</strong>, and then you <strong>build</strong> and <strong>preview</strong> before <strong>pushing</strong> to SFCC.</li></ul><h3 id="column-name-mapping" tabindex="-1">Column name mapping <a class="header-anchor" href="#column-name-mapping" aria-label="Permalink to &quot;Column name mapping&quot;">​</a></h3><p>The parser recognizes many column name variations. All accepted aliases are defined in <code>src/config/excel.config.js</code> (<code>HEADER_ALIASES</code>). For example, the canonical <code>REFRESH_NAME</code> field accepts columns named &quot;REFRESH_NAME&quot;, &quot;REFRESH NAME&quot;, &quot;PROJECT SUMMARY&quot;, &quot;REFRESH&quot;, &quot;SUMMARY&quot;, &quot;INITIATIVE&quot;, or &quot;INITIATIVE NAME&quot;. To add a new alias, edit the relevant array in <code>excel.config.js</code>.</p><h2 id="how-it-drives-the-pipeline" tabindex="-1">How it drives the pipeline <a class="header-anchor" href="#how-it-drives-the-pipeline" aria-label="Permalink to &quot;How it drives the pipeline&quot;">​</a></h2><ol><li><strong>Pull</strong> — Fetches data from your configured source (local Excel or Smartsheet), parses it, and writes <code>dev-env/{brand}/refreshes/{date}/r#/refresh.json</code>.</li><li><strong>Build</strong> — Turns refresh JSON into HTML and OCAPI payload for that date.</li><li><strong>Preview</strong> — Composes zones and opens preview links.</li><li><strong>Push</strong> — Validates and syncs to SFCC staging.</li></ol><p>All of this is driven by the Excel columns and structure. See <a href="./wireframe-format.html">Wireframe format</a> and <a href="./how-changeouts-flow.html">How changeouts flow</a>.</p><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td>1</td><td><code>make pull</code></td><td>Fetch Excel/Smartsheet → refresh JSONs; auto-build new dates; open status hub</td></tr><tr><td>2</td><td><code>make build</code></td><td>Generate HTML + OCAPI for selected date</td></tr><tr><td>3</td><td><code>make preview</code></td><td>View preview links</td></tr><tr><td>4</td><td><code>make push</code></td><td>Validate and sync to SFCC</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./wireframe-format.html">Wireframe format</a> — Required and optional columns, aliases, parent-child rows.</li><li><a href="./how-changeouts-flow.html">How changeouts flow</a> — Pull → build → preview → push with copy-paste commands.</li><li><a href="./validation-and-fixes.html">Validation and fixes</a> — Warnings/errors and how to fix them in Excel.</li><li><a href="./best-practices.html">Best practices</a> — Naming, approvals, timing, hotfix policy.</li></ul>',13)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
